import type { ReactNode } from "react";
export function PageHeader({ title, description, actions }: { title: string; description?: string; actions?: ReactNode }) { return <header className="mb-8 flex flex-col gap-5 border-b border-[#ddd8ce] pb-7 sm:flex-row sm:items-end sm:justify-between"><div><div className="eyebrow mb-2">Your procurement</div><h1 className="display-type text-[2rem] leading-tight sm:text-[2.3rem]">{title}</h1>{description ? <p className="mt-2 max-w-2xl text-sm leading-6 text-[#756d63]">{description}</p> : null}</div>{actions ? <div className="flex shrink-0 items-center gap-2">{actions}</div> : null}</header>; }
